var t=[{title:`Ce que change la forme`,text:`Dans certains mouvements, le poids suspendu peut se déplacer autour de votre poignet ou de votre avant-bras, et il s’équilibre autrement qu’un haltère. Les squats goblet, les soulevés de terre et les portages utilisent le kettlebell de façon assez simple. Les épaulés, les arrachés et les autres gestes balistiques ajoutent de l’élan et des exigences de coordination qui peuvent être trop élevés pour les débutants.`},{title:`Commencez par les bases`,text:`Apprenez une charnière de hanche contrôlée et un soulevé de terre simple avant d’essayer un swing, et faites des squats goblet, des soulevés de terre, des rowings ou des portages avant un travail balistique très coordonné. Choisissez un kettlebell assez léger pour des mouvements réguliers répétés, mais assez lourd pour vous stimuler. Le sexe ou l’âge seuls ne peuvent pas indiquer le bon poids de départ ; votre force, votre expérience et l’exercice choisi comptent.`},{title:`Mécanique du swing`,text:`Dans un swing à deux mains courant, le kettlebell part d’entre vos jambes jusqu’à peu près la hauteur de la poitrine, propulsé par une puissante extension des hanches et non par l’élévation des bras. Gardez la colonne contrôlée, laissez vos genoux fléchir un peu et guidez le kettlebell sur le même arc à chaque fois. Ne transformez pas l’exercice en squat profond suivi d’une élévation frontale.`},{title:`Sécurité et progression`,text:`Pratiquez quand le sol, vos mains et l’espace autour de vous sont dégagés et secs. Laissez assez de place devant et derrière vous pour la trajectoire du kettlebell. Arrêtez-vous quand votre prise ou votre technique de charnière commence à se dégrader. Ne passez des soulevés de terre et des charnières contrôlées à de courtes séries de swings que lorsque vous maîtrisez le mouvement de façon fiable.`},{title:`Avec TrainUp`,text:`Indiquez avec précision dans Profil la taille de votre espace au sol, la hauteur de votre plafond et votre type de sol. Votre programme ne choisit que des exercices adaptés à votre espace, votre surface, vos limitations et votre coordination, ce qui compte pour les mouvements balancés dans une petite pièce.`}];var r=[{label:`ACE : technique du swing de kettlebell à deux mains`,url:`https://www.acefitness.org/continuing-education/certified/january-2025/8788/the-ace-do-it-better-series-the-two-handed-kettlebell-swing/`},{label:`Bibliothèque d’exercices de l’ACE`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`},{label:`Mayo Clinic : technique de musculation (2026)`,url:`https://www.mayoclinic.org/healthy-lifestyle/fitness/in-depth/weight-training/art-20045842`}];var a={sections:t,sources:r};export{a as default,t as sections,r as sources};